vector<int> solve(string s) {
    unordered_map<string, vector<int>> memo;
    function<vector<int>(const string&)> dfs = [&](const string& str) -> vector<int> {
        auto it = memo.find(str);
        if (it != memo.end()) return it->second;

        vector<int> result;
        for (size_t i = 0; i < str.size(); ++i) {
            char c = str[i];
            if (c == '+' || c == '-' || c == '*') {
                vector<int> left  = dfs(str.substr(0, i));
                vector<int> right = dfs(str.substr(i + 1));
                for (int x : left) {
                    for (int y : right) {
                        if (c == '+') result.push_back(x + y);
                        else if (c == '-') result.push_back(x - y);
                        else result.push_back(x * y);
                    }
                }
            }
        }
        if (result.empty()) {
            result.push_back(stoi(str));
        }
        memo[str] = result;
        return result;
    };
    return dfs(s);
}

