#include <functional>
#include <unordered_map>

bool subsetSum(int arr[], int n, int sum)
{
    if (sum == 0) return true;
    if (n < 0 || sum < 0) return false;

    std::unordered_map<long long, char> memo;
    std::function<bool(int,int)> dfs = [&](int i, int s) -> bool {
        if (s == 0) return true;
        if (i < 0 || s < 0) return false;

        long long key = ( (static_cast<long long>(i) << 32) ^ (static_cast<unsigned int>(s)) );
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        bool include = dfs(i - 1, s - arr[i]);
        bool exclude = dfs(i - 1, s);
        bool res = include || exclude;
        memo[key] = res;
        return res;
    };

    return dfs(n, sum);
}

