    auto key = std::make_tuple(idx, currOr, maxOr, (const vector<int>*)&nums);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    int takeCount = countSubsets(idx + 1, currOr | nums[idx], nums, maxOr);
