using namespace std;

int countstrings(int n, int start) {
    if (n == 0) return 1;
    if (start < 0) start = 0;
    if (start > 4) return 0;
    // f(len, s) = sum_{i=s..4} f(len-1, i)
    // keep only the current layer, O(n * 5) time, O(5) memory
    long long dp[5];
    for (int i = 0; i < 5; ++i) dp[i] = 1; // len = 0
    for (int len = 1; len <= n; ++len) {
        long long suffix = 0;
        long long ndp[5];
        for (int i = 4; i >= 0; --i) {
            suffix += dp[i];
            ndp[i] = suffix;
        }
        for (int i = 0; i < 5; ++i) dp[i] = ndp[i];
    }
    return static_cast<int>(dp[start]);
}

int countVowelStrings(int n) {
    return countstrings(n, 0);
}

