bool isSubSequence(char str1[],char str2[],int m,int n) {
    if(m==0) return true;
    if(n==0) return false;
    vector<char> prev(n+1, 1), cur(n+1, 0);
    for(int i=1;i<=m;++i){
        cur[0]=0;
        for(int j=1;j<=n;++j){
            if(str1[i-1]==str2[j-1])
                cur[j]=prev[j-1];
            else
                cur[j]=prev[j];
        }
        prev.swap(cur);
    }
    return prev[n];
}

