long long Count(int i) {
    if (i == 0) return 1;
    if (i < 0) return 0;
    static vector<long long> memo;
    if (memo.empty()) {
        memo.push_back(1); // memo[0] = 1
    }
    if (i < (int)memo.size()) {
        return memo[i];
    }
    for (int k = (int)memo.size(); k <= i; ++k) {
        memo.push_back( (k + 1) + 2 * memo[k - 1] );
    }
    return memo[i];
}

