int factorial(int n) {
    if (n == 0) return 1;
    static std::vector<int> memo;
    if (memo.empty()) {
        memo.push_back(1);
    }
    if (n < (int)memo.size()) {
        return memo[n];
    }
    int start = memo.size();
    memo.resize(n + 1);
    for (int i = start; i <= n; ++i) {
        memo[i] = memo[i - 1] * i;
    }
    return memo[n];
}

