const int MAX = INT_MAX;
int Min = INT_MAX;

int minOperation(string& s, int i, int j, int count) {
    int n = (int)s.size();
    static vector<vector<int>> memo;
    static string last;
    if (s != last) {
        last = s;
        memo.assign(n, vector<int>(n, -1));
        Min = INT_MAX;
    }
    if ((i >= n && j < 0) || i == j) return MAX;
    if (i >= n || j < 0) return count;
    if (i > j) return count;
    if (s[i] == s[j] || count >= Min) return count;

    if (memo[i][j] != -1) {
        int res = count + memo[i][j];
        if (res < Min) Min = res;
        return res;
    }

    int left  = minOperation(s, i + 1, j, count + 1);
    int right = minOperation(s, i, j - 1, count + 1);
    int best = min(left, right);

    memo[i][j] = best - count;
    if (best < Min) Min = best;
    return best;
}

