using namespace std;
int numberOfWays(int n,int k) {
    if (n == 0) return 1;
    if (k == 0) return 1;
    vector<vector<int>> memo(n + 1, vector<int>(k + 1, -1));
    function<int(int,int)> solve = [&](int nn, int kk) -> int {
        if (nn == 0) return 1;
        if (kk == 0) return 1;
        if (nn < 0) return 0;
        if (memo[nn][kk] != -1) return memo[nn][kk];
        long long coin = 1LL << kk;
        int res;
        if (nn >= coin) {
            res = solve(nn - (int)coin, kk) + solve(nn, kk - 1);
        } else {
            res = solve(nn, kk - 1);
        }
        memo[nn][kk] = res;
        return res;
    };
    return solve(n, k);
}

