    if (memo.empty()) {
        memo.push_back(1); // memo[0] = 1
    }
    if (n < (int)memo.size()) {
        return memo[n];
    }
    int start = memo.size();
    memo.resize(n + 1);
    for (int i = start; i <= n; ++i) {
