const int Mod = 1e9 + 7;

int power(int X, int Y, int Mod) {
    if (Y == 0) return 1;
    long long p = power(X, Y / 2, Mod);
    p = (p * p) % Mod;
    if (Y & 1) {
        p = (1LL * X * p) % Mod;
    }
    return int(p);
}

static unordered_map<int,int> factMemo;
static unordered_map<int,int> invFactMemo;

int factorial(int N) {
    if (N <= 0) return 1;
    auto it = factMemo.find(N);
    if (it != factMemo.end()) return it->second;
    long long fact = 1;
    for (int i = 1; i <= N; ++i) {
        fact = (fact * i) % Mod;
    }
    int res = int(fact);
    factMemo[N] = res;
    return res;
}

int Inversefactorial(int N) {
    if (N <= 0) return 1;
    auto it = invFactMemo.find(N);
    if (it != invFactMemo.end()) return it->second;
    int fact = factorial(N);
    int inv = power(fact, Mod - 2, Mod);
    invFactMemo[N] = inv;
    return inv;
}

int nck(int N, int K) {
    if (K < 0 || K > N) return 0;
    int factN = factorial(N);
    int invFactK = Inversefactorial(K);
    int invFactNK = Inversefactorial(N - K);
    long long res = 1LL * factN * invFactK % Mod;
    res = res * invFactNK % Mod;
    return int(res);
}

int TotalWaYs(int N, int M) {
    if ((N + M) % 3 != 0) return 0;
    int s = (N + M) / 3;
    int X = N - s;
    int Y = M - s;
    if (X < 0 || Y < 0) return 0;
    return nck(X + Y, Y);
}

