int getTotalNumberOfSequences(int m,int n) {
    if (m < 0 || n < 0) return 0;
    if (m < n) return 0;
    if (n == 0) return 1;
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= m; ++i) dp[i][0] = 1;
    for (int j = 1; j <= n; ++j) {
        for (int i = 0; i <= m; ++i) {
            if (i < j) { dp[i][j] = 0; continue; }
            int a = (i > 0) ? dp[i - 1][j] : 0;
            int b = dp[i / 2][j - 1];
            dp[i][j] = a + b;
        }
    }
    return dp[m][n];
}

