using namespace std;

int binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k > n - k) k = n - k;
    static vector<vector<int>> dp;
    if (dp.empty()) {
        dp.push_back(vector<int>(1, 1));
    }
    while ((int)dp.size() <= n) {
        int sz = (int)dp.size();
        vector<int> row(sz + 1, 0);
        row[0] = row[sz] = 1;
        for (int i = 1; i < sz; ++i) {
            row[i] = dp[sz - 1][i - 1] + dp[sz - 1][i];
        }
        dp.push_back(move(row));
    }
    return dp[n][k];
}

