unsigned int countSetBits(unsigned int L, unsigned int R) {
    if (L > R) return 0;
    // DP table sized from arguments, no fixed constant
    vector<unsigned int> bits(R + 1);
    bits[0] = 0;
    for (unsigned int i = 1; i <= R; ++i) {
