    static thread_local std::vector<std::vector<int>> memo;
    ++depth;
    if (depth == 1) {
        memo.assign(n + 1, std::vector<int>(W + 1, -1));
    }
    if (n == 0 || W == 0) {
        --depth;
        return 0;
    }
    if (memo[n][W] != -1) {
        --depth;
        return memo[n][W];
    }
    int res;
    if (w[n] > W) {
        res = packRecursive(n - 1, W, w, v);
    } else {
        res = std::max(v[n] + packRecursive(n - 1, W - w[n], w, v),
                       packRecursive(n - 1, W, w, v));
    }
    memo[n][W] = res;
    --depth;
    if (depth == 0) {
        memo.clear();
    }
    return res;
}

