    function<int(int,int)> solve = [&](int i,int j)->int {
        if(i==0 || j==0) return 0;
        int &res = memo[i][j];
        if(res != -1) return res;
        if(X[i-1]==Y[j-1]) res = 1 + solve(i-1,j-1);
        else res = solve(i-1,j);
        return res;
    };
    return solve(n,m);
}

