bool isScramble(string s1, string s2) {
    if (s1.size() != s2.size()) return false;
    unordered_map<string, bool> memo;
    function<bool(string,string)> dp = [&](string a, string b) -> bool {
        if (a == b) return true;
        if (a.size() != b.size()) return false;
        string key = a + "#" + b;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        array<int,256> cnt{};
        for (unsigned char c : a) cnt[c]++;
        for (unsigned char c : b) {
            if (--cnt[c] < 0) {
                memo[key] = false;
                return false;
            }
        }
        int n = (int)a.size();
        for (int i = 1; i < n; ++i) {
            if (dp(a.substr(0,i), b.substr(0,i)) && dp(a.substr(i), b.substr(i))) {
                memo[key] = true;
                return true;
            }
            if (dp(a.substr(0,i), b.substr(n-i)) && dp(a.substr(i), b.substr(0,n-i))) {
                memo[key] = true;
                return true;
            }
        }
        memo[key] = false;
        return false;
    };
    return dp(s1, s2);
}

