    for(int i=0;i<N;i++) if(arr[i]>maxVal) maxVal = arr[i];
    if(maxVal < 1) maxVal = 1;
    // memoise gcd for all pairs up to maxVal -> each pair solved once
    vector<vector<int>> memo(maxVal+1, vector<int>(maxVal+1, 0));
