using namespace std;
int zigzag(int n, int k) {
    if (n < 0 || k < 0) return 0;
    if (k == 0) return n == 0 ? 1 : 0;
    if (k > n) return 0;

    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    dp[0][0] = 1;
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (i == 0 && j == 0) continue;
            if (j == 0) { dp[i][j] = 0; continue; }
            dp[i][j] = dp[i][j - 1] + dp[i - 1][i - j];
        }
    }
    return dp[n][k];
}

