int power(int num, unsigned int n) {
    if (n == 0) return 1;
    long long result = 1;
    long long base = num;
    unsigned int exp = n;
    while (exp > 0) {
        if (exp & 1U) result *= base;
        base *= base;
        exp >>= 1;
    }
    return static_cast<int>(result);
}

