int KvisibleFromLeft(int N,int K) {
    if (K < 0 || K > N) return 0;
    vector<vector<int>> dp(N + 1, vector<int>(K + 1, 0));
    dp[0][0] = 1;
    for (int n = 1; n <= N; ++n) {
        int kmax = min(n, K);
        for (int k = 1; k <= kmax; ++k) {
            dp[n][k] = dp[n - 1][k - 1] + (n - 1) * dp[n - 1][k];
        }
        if (K >= n) dp[n][n] = 1;
    }
    return dp[N][K];
}

