int findMinInsertions(char str[],int l,int h) {
    int n = strlen(str);
    vector<vector<int>> memo(n, vector<int>(n, -1));
    function<int(int,int)> solve = [&](int i,int j)->int {
        if(i > j) return INT_MAX;
        if(i == j) return 0;
        if(i == j - 1) return (str[i] == str[j]) ? 0 : 1;
        int &res = memo[i][j];
        if(res != -1) return res;
        if(str[i] == str[j]) {
            res = solve(i + 1, j - 1);
        } else {
            res = min(solve(i + 1, j), solve(i, j - 1)) + 1;
        }
        return res;
    };
    return solve(l, h);
}

