int splitIntoPrimes(string number) {
    int n = number.length();
    if (n == 0) return 0;
    const int INF = INT_MAX / 2;
    vector<int> memo(n + 1, INF);
    memo[n] = 0; // empty suffix
    for (int i = n - 1; i >= 0; --i) {
        int best = INF;
        for (int len = 1; len <= 6 && i + len <= n; ++len) {
            string sub = number.substr(i, len);
            if (checkPrime(sub)) {
                if (memo[i + len] != INF) {
                    best = min(best, 1 + memo[i + len]);
                }
            }
        }
        memo[i] = best;
    }
    return memo[0] == INF ? -1 : memo[0];
}

