using namespace std;
int countSortedArrays(int start,int m,int size,int n) {
    if (size > m) return 0;
    if (size == m) return 1;
    if (start > n) return 0;
    int rows = n - start + 2;               // s = start .. n+1
    vector<vector<int>> dp(rows, vector<int>(m + 1, 0));
    // base row s = n+1
    dp[rows - 1][m] = 1;
    for (int s = n; s >= start; --s) {
        int idx = s - start;
        dp[idx][m] = 1;
        for (int sz = m - 1; sz >= size; --sz) {
            // dp[s][sz] = dp[s][sz+1] + dp[s+1][sz]
            dp[idx][sz] = dp[idx][sz + 1] + dp[idx + 1][sz];
        }
    }
    return dp[0][size];
}

