using namespace std;
int FindMaxS(int X,int Y,int Z,int n,vector<int >&A,vector<int >&B,vector<int >&C) {
    if (X < 0 || Y < 0 || Z < 0) return INT_MIN;
    if (n < 0) return 0;
    struct Key { int x,y,z,i; bool operator==(Key const& o) const noexcept { return x==o.x && y==o.y && z==o.z && i==o.i; } };
    struct KeyHash { size_t operator()(Key const& k) const noexcept {
        size_t h = std::hash<int>{}(k.x);
        h ^= std::hash<int>{}(k.y + 0x9e3779b9 + (h<<6) + (h>>2));
        h ^= std::hash<int>{}(k.z + 0x9e3779b9 + (h<<6) + (h>>2));
        h ^= std::hash<int>{}(k.i + 0x9e3779b9 + (h<<6) + (h>>2));
        return h;
    }};
    unordered_map<Key,int,KeyHash> memo;
    function<int(int,int,int,int)> dfs = [&](int x,int y,int z,int i)->int {
        if (x < 0 || y < 0 || z < 0) return INT_MIN;
        if (i < 0) return 0;
        Key k{x,y,z,i};
        auto it = memo.find(k);
        if (it != memo.end()) return it->second;
        int ch = A[i] + dfs(x-1, y,   z,   i-1);
        int ca = B[i] + dfs(x,   y-1, z,   i-1);
        int co = C[i] + dfs(x,   y,   z-1, i-1);
        int no = dfs(x,   y,   z,   i-1);
        int best = max(ch, max(ca, max(co, no)));
        memo.emplace(k, best);
        return best;
    };
    return dfs(X, Y, Z, n);
}

