using namespace std;
int Hosoya(int n,int m) {
    if (n < 0 || m < 0) return 0;
    // DP table sized from the arguments, no fixed constant
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 0; i <= n; ++i) {
        int jmax = min(i, m);
        for (int j = 0; j <= jmax; ++j) {
            if ((i == 0 && j == 0) || (i == 1 && j == 0) || (i == 1 && j == 1) || (i == 2 && j == 1)) {
                dp[i][j] = 1;
            } else if (i > j) {
                dp[i][j] = dp[i - 1][j] + (i >= 2 ? dp[i - 2][j] : 0);
            } else if (i == j) {
                dp[i][j] = dp[i - 1][j - 1] + (i >= 2 ? dp[i - 2][j - 2] : 0);
            } else {
                dp[i][j] = 0;
            }
        }
    }
    return dp[n][m];
}
