using namespace std;
int numberOfUniqueOutcomes(int N,int S) {
    if (S < N) return 0;
    // base cases as intended: N==1 || N==S
    // DP table sized from the arguments, no fixed constant
    vector<vector<int>> dp(N + 1, vector<int>(S + 1, 0));
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= S; ++j) {
            if (j < i) {
                dp[i][j] = 0;
            } else if (i == 1 || i == j) {
                dp[i][j] = 1;
            } else {
                int a = dp[i - 1][j - 1];
                int b = j >= 2 ? dp[i - 1][j - 2] : 0;
                dp[i][j] = a + b;
            }
        }
    }
    return dp[N][S];
}

