const int mod=1000000007;
int calculate(int pos,int left,int k,int L,int R) {
    if (pos > k) return 0;
    int steps = k - pos;
    if (steps < 0 || left < 0) return 0;
    long long minSum = 1LL * steps * L;
    long long maxSum = 1LL * steps * R;
    if (left < minSum || left > maxSum) return 0;
    vector<vector<int>> dp(steps + 1, vector<int>(left + 1, 0));
    dp[0][0] = 1;
    for (int s = 1; s <= steps; ++s) {
        long long sMin = 1LL * s * L;
        long long sMax = 1LL * s * R;
        int start = (int)max<long long>(sMin, 0);
        int end = (int)min<long long>(sMax, left);
        for (int sum = start; sum <= end; ++sum) {
            long long ways = 0;
            for (int v = L; v <= R && v <= sum; ++v) {
                ways += dp[s - 1][sum - v];
            }
            dp[s][sum] = int(ways % mod);
        }
    }
    return dp[steps][left];
}
int countWaystoDivide(int n,int k,int L,int R) {
    return calculate(0,n,k,L,R);
}

