int BinomialCoefficient(int n, int k) {
  if (n < k || k < 0) {
    return 0;
  }
  if (k == 0 || k == n) {
    return 1;
  }
  if (k > n - k) k = n - k;
  vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
  for (int i = 0; i <= n; ++i) {
    dp[i][0] = 1;
    for (int j = 1; j <= k && j <= i; ++j) {
      dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
    }
  }
  return dp[n][k];
}

