int countSubstrs(string str,int i,int j,int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    int len = j - i + 1;
    // For correct calls n == len. The DP is performed on the interval [i,j].
    vector<vector<int>> memo(len, vector<int>(len, -1));
    function<int(int,int)> solve = [&](int ii, int jj) -> int {
