int removeBoxesHelper(const vector<int>& boxes, int l, int r, int k, int lookup[100][100][100]) {
    if (l > r) return 0;
    int n = static_cast<int>(boxes.size());
    if (k >= n) k = n - 1;

    static vector<vector<vector<int>>> memo;
    static int memo_n = -1;
    if (memo_n != n) {
        memo.assign(n, vector<vector<int>>(n, vector<int>(n, -1)));
        memo_n = n;
    }
    if (memo[l][r][k] != -1) return memo[l][r][k];

    int ll = l;
    int kk = k;
    while (ll + 1 <= r && boxes[ll + 1] == boxes[ll]) {
        ++ll;
        ++kk;
    }

    int res = removeBoxesHelper(boxes, ll + 1, r, 0, lookup) + (kk + 1) * (kk + 1);
    for (int i = ll + 1; i <= r; ++i) {
        if (boxes[i] == boxes[ll]) {
            int cand = removeBoxesHelper(boxes, ll + 1, i - 1, 0, lookup)
                     + removeBoxesHelper(boxes, i, r, kk + 1, lookup);
            if (cand > res) res = cand;
        }
    }
    memo[l][r][k] = res;
    return res;
}

