using namespace std;
int eulerian(int n, int m) {
    if (m >= n || n == 0) return 0;
    if (m == 0) return 1;
    // DP table sized from the arguments, O(n*m) time, O(n*m) memory
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m && j < i; ++j) {
            long long fromLeft  = (j > 0) ? 1LL * (i - j) * dp[i - 1][j - 1] : 0;
            long long fromSame  = 1LL * (j + 1) * dp[i - 1][j];
            dp[i][j] = int(fromLeft + fromSame);
        }
    }
    return dp[n][m];
}

