int gcd(int a,int b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int lcm(int a,int b) {
    if (a == 0 || b == 0) return 0;
    long long g = gcd(a,b);
    long long res = 1LL * llabs((long long)a) / g * llabs((long long)b);
    if (res > INT_MAX) return INT_MAX;
    return (int)res;
