}
int findNthTerm(int a,int b,int c,int n) {
    // lcm values are constant for a given a,b,c -> compute once
    int lcm_ab = lcm(a,b);
    int lcm_bc = lcm(b,c);
    int lcm_ac = lcm(a,c);
    int lcm_abc = lcm(lcm_ab, c); // = lcm(a,lcm(b,c))
    int low = 1, high = INT_MAX, mid;
    while (low < high) {
        mid = low + (high - low) / 2;
        int cnt = (mid / a) + (mid / b) + (mid / c)
                - (mid / lcm_ab) - (mid / lcm_bc) - (mid / lcm_ac)
                + (mid / lcm_abc);
        if (cnt < n) low = mid + 1;
        else high = mid;
    }
    return low;
}

