#include <unordered_map>
#include <functional>

int steps(int source,int step,int dest) {
    unordered_map<unsigned long long,int> memo;
    function<int(int,int)> dfs = [&](int s,int st)->int {
        unsigned long long key = ((unsigned long long)(unsigned int)s << 32) | (unsigned int)st;
        auto it = memo.find(key);
        if(it != memo.end()) return it->second;
        int res;
        if(abs(s) > dest) {
            res = INT_MAX;
        } else if(s == dest) {
            res = st;
        } else {
            int pos = dfs(s + st + 1, st + 1);
            int neg = dfs(s - st - 1, st + 1);
            res = min(pos, neg);
        }
        memo[key] = res;
        return res;
    };
    return dfs(source, step);
}

