    if(s[i]== s[j]) return count;
    if(i>=s.size())return minOperation(s,i,j-1,count+1);
    else if(j<0)return minOperation(s,i+1,j,count+1);
    else return min(minOperation(s,i,j-1,count+1), minOperation(s,i+1,j,count+1));
