int DistRecursion(string S,int i,int dist) {
    int n = S.length();
    static string cachedS;
    static vector<vector<int>> memo;
    static int cachedN = -1;
    if (S != cachedS || cachedN != n) {
        cachedS = S;
        cachedN = n;
        memo.assign(n + 1, vector<int>(2 * n + 1, -2));
    }
    int offset = cachedN;
    if (i == n) return abs(dist);
    int idx = dist + offset;
    if (idx < 0 || idx >= (int)memo[i].size()) {
        if (S[i] == 'L') return DistRecursion(S, i + 1, dist - 1);
        if (S[i] == 'R') return DistRecursion(S, i + 1, dist + 1);
        return max(DistRecursion(S, i + 1, dist - 1), DistRecursion(S, i + 1, dist + 1));
    }
    int &res = memo[i][idx];
    if (res != -2) return res;
    if (S[i] == 'L') {
        res = DistRecursion(S, i + 1, dist - 1);
    } else if (S[i] == 'R') {
        res = DistRecursion(S, i + 1, dist + 1);
    } else {
        res = max(DistRecursion(S, i + 1, dist - 1), DistRecursion(S, i + 1, dist + 1));
    }
    return res;
}

