    if(bCount < 0 || cCount < 0) return 0;
    if(n == 0) return 1;
    if(bCount == 0 && cCount == 0) return 1;

    // memo table sized from the arguments, no fixed constants
    vector<vector<vector<int>>> memo(n + 1, vector<vector<int>>(bCount + 1, vector<int>(cCount + 1, -1)));

    function<int(int,int,int)> solve = [&](int i,int b,int c) -> int {
        if(b < 0 || c < 0) return 0;
        if(i == 0) return 1;
        if(b == 0 && c == 0) return 1;
        int &res = memo[i][b][c];
        if(res != -1) return res;
        res = solve(i - 1, b, c)
            + solve(i - 1, b - 1, c)
            + solve(i - 1, b, c - 1);
        return res;
    };

    return solve(n, bCount, cCount);
}

