ll sumPows(ll a, int k) {
    if (k <= 0) return 0;
    vector<ll> memo(k + 1, 0);
    vector<char> done(k + 1, 0);
    function<ll(int)> dfs = [&](int n) -> ll {
        if (n == 0) return 0;
        if (done[n]) return memo[n];
        ll res;
        if (n % 2 == 1) {
            ll sub = dfs(n - 1);
            res = a * (1 + sub);
        } else {
            ll half = dfs(n / 2);
            ll sub = dfs(n / 2 - 1);
            res = half * (1 + half - sub);
        }
        done[n] = 1;
        memo[n] = res;
        return res;
    };
    return dfs(k);
}

