int fact(int n) {
    static vector<int> memo;
    static int computed = -1;
    if (n < 0) return 1;
    if (memo.empty()) {
        memo.push_back(1);
        computed = 0;
    }
    if (n <= computed) return memo[n];
    for (int i = computed + 1; i <= n; ++i) {
        long long v = (long long)memo.back() * i;
        memo.push_back((int)v);
    }
    computed = n;
    return memo[n];
}
