#include <iostream>
#include <vector>
#include <functional>
using namespace std;

int count(string a, string b, int m, int n) {
    vector<vector<int>> memo(m + 1, vector<int>(n + 1, -1));
    function<int(int,int)> dfs = [&](int i, int j) -> int {
        if (i == 0 && j == 0) return 1;
        if (i == 0) return 0;
        if (j == 0) return 0;               // prevents UB on b[j-1]
        if (memo[i][j] != -1) return memo[i][j];
        if (a[i - 1] == b[j - 1])
            memo[i][j] = dfs(i - 1, j - 1) + dfs(i - 1, j);
        else
            memo[i][j] = dfs(i - 1, j);
        return memo[i][j];
    };
    return dfs(m, n);
}

