using namespace std;

bool isScramble(string S1, string S2) {
    if (S1.size() != S2.size()) return false;
    int n = (int)S1.size();
    if (n == 0) return true;

    // prefix sums for O(26) multiset pruning, sized from the arguments
    vector<array<int,26>> pre1(n+1), pre2(n+1);
    for (auto &a : pre1) a.fill(0);
    for (auto &a : pre2) a.fill(0);
    for (int i = 0; i < n; ++i) {
        pre1[i+1] = pre1[i];
        pre1[i+1][S1[i]-'a']++;
        pre2[i+1] = pre2[i];
        pre2[i+1][S2[i]-'a']++;
    }
    auto sameMultiset = [&](int i1, int i2, int len)->bool {
        for (int k = 0; k < 26; ++k)
            if (pre1[i1+len][k] - pre1[i1][k] != pre2[i2+len][k] - pre2[i2][k])
                return false;
        return true;
    };

    unordered_map<string,bool> memo;
    function<bool(int,int,int)> dfs = [&](int i1, int i2, int len)->bool {
        if (len == 0) return true;
        if (len == 1) return S1[i1] == S2[i2];
        string key = to_string(i1) + '#' + to_string(i2) + '#' + to_string(len);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        if (S1.compare(i1, len, S2, i2, len) == 0) {
            memo[key] = true;
            return true;
        }
        if (!sameMultiset(i1, i2, len)) {
            memo[key] = false;
            return false;
        }
        for (int k = 1; k < len; ++k) {
            // no swap
            if (dfs(i1, i2, k) && dfs(i1+k, i2+k, len-k)) {
                memo[key] = true;
                return true;
            }
            // swap
            if (dfs(i1, i2+len-k, k) && dfs(i1+k, i2, len-k)) {
                memo[key] = true;
                return true;
            }
        }
        memo[key] = false;
        return false;
    };

    return dfs(0, 0, n);
}

